SET @prov_c := ( SELECT provincecode FROM sys_config LIMIT 1 );
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

DROP TEMPORARY TABLE IF EXISTS tx;
CREATE TEMPORARY TABLE IF NOT EXISTS tx(PRIMARY KEY(HOSPCODE,PID,DATE_SERV)
) ENGINE=MyISAM IGNORE AS 
SELECT h.hoscode as hospcode, h.hosname, p.PID, p.CID, p.NAME, p.LNAME, p.SEX, p.BIRTH, p.HID, p.addr
, p.check_vhid, p.NATION, p.DISCHARGE, p.TYPEAREA
,e.source,e.date_serv,e.typeout,e.causeout,e.referouthosp,c.zonecode,e.DIAGCODE,e.DIAGTYPE
,IF(e.causeout  in(1,2) AND ((e.typeout  in(3) AND e.source in('opdcase')) OR (e.typeout  in(4) AND e.source in('ipdcase')) ),'นับcase','ไม่นับผลงาน') AS RESULT
FROM t_refer_4pa  e 
		INNER JOIN chospital h ON e.HOSPCODE=h.hoscode AND h.provcode IN(@prov_c)  {where}
		INNER JOIN chospital h1 ON e.referouthosp=h1.hoscode  
		INNER JOIN cchangwat c ON h1.provcode=c.changwatcode
		INNER JOIN t_person_db p ON e.HOSPCODE=p.hospcode AND e.pid=p.pid
		LEFT JOIN (SELECT hospcode,result FROM s_referout4pa WHERE b_year in(@b_year+542) )   
			s ON  e.hospcode=s.hospcode
WHERE (s.hospcode is NULL OR s.hospcode is NOT NULL )
GROUP BY e.HOSPCODE,e.pid,e.date_serv;

SELECT
h.hoscode, h.hosname, d.PID, d.CID, d.NAME, d.LNAME, d.SEX
, d.BIRTH, d.HID, d.addr, d.check_vhid, d.NATION, d.TYPEAREA,d.DISCHARGE
,d.source,d.date_serv,d.typeout,d.causeout,d.referouthosp,d.zonecode,d.DIAGCODE,d.DIAGTYPE,d.RESULT
FROM
tx d INNER JOIN chospital h ON d.hospcode = h.hoscode
WHERE 1=1 {where}
